package in.finseq.insurance;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;
public class PolicyDetailActivity extends FinseqActivity{
 int id;JSONObject record;LinearLayout root,info;
 public void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra("policy_id",0);if(id<=0){finish();return;}root=Ui.column(this);Ui.appHeader(root,this,"Policy Details");LinearLayout body=Ui.contentColumn(this);root.addView(body);info=Ui.card(this);body.addView(info);setContentView(Ui.scroll(this,root));load();}
 void load(){Ui.run(this,()->{try{JSONObject snapshot=ApiClient.get(this,"/api/v1/sync");JSONArray p=snapshot.optJSONArray("policies");JSONObject m=null;for(int i=0;p!=null&&i<p.length();i++){JSONObject x=p.optJSONObject(i);if(x!=null&&x.optInt("id")==id){m=x;break;}}JSONObject f=m;Ui.ui(this,()->{if(f==null){info.addView(Ui.sub(this,"Policy missing or access denied"));return;}record=f;render();});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void render(){info.removeAllViews();info.addView(Ui.text(this,record.optString("customer","Customer"),20,true));info.addView(Ui.sub(this,record.optString("policy_number")+" · "+record.optString("insurer")));info.addView(Ui.sub(this,record.optString("type")+" / "+record.optString("subtype")+(record.optString("vehicle").isEmpty()?"":" · "+record.optString("vehicle"))));info.addView(Ui.text(this,"Expiry: "+record.optString("expiry_date")+" · Premium: "+Ui.money(record.optDouble("premium")),15,true));info.addView(Ui.badge(this,record.optString("status","Recorded"),record.optDouble("due")>0?Ui.RED:Ui.GREEN));detail("Issue Date",record.optString("issue_date"));detail("Start Date",record.optString("start_date"));detail("Expiry Date",record.optString("expiry_date"));detail("Product",record.optString("product_name"));detail("Vehicle",record.optString("vehicle"));detail("Premium paid by",record.optString("paid_by"));detail("Customer paid",Ui.money(record.optDouble("paid")));detail("Customer due",Ui.money(record.optDouble("due")));if(record.optDouble("inspection")>0){detail("Inspection charge",Ui.money(record.optDouble("inspection")));detail("Inspection by",record.optString("inspection_done_by"));detail("Inspection location",record.optString("inspection_location"));}if(record.optDouble("idv")>0)detail("IDV",Ui.money(record.optDouble("idv")));if(record.optDouble("sum_insured")>0)detail("Sum insured",Ui.money(record.optDouble("sum_insured")));detail("Covered members",record.optString("members"));if(record.optBoolean("has_pdf")){Button pdf=Ui.greenButton(this,"Preview PDF · Pinch to Zoom");pdf.setOnClickListener(v->startActivity(new Intent(this,PdfPreviewActivity.class).putExtra("policy_id",id)));info.addView(pdf);}Button share=Ui.button(this,"Share Policy Copy · Review Template");share.setEnabled(record.optBoolean("has_pdf"));share.setOnClickListener(v->PolicySharing.whatsapp(this,id,false));info.addView(share);Button email=Ui.button(this,"Email Policy PDF · Review Template");email.setEnabled(record.optBoolean("has_pdf"));email.setOnClickListener(v->PolicySharing.email(this,id,false));info.addView(email);if("admin".equalsIgnoreCase(Session.role(this))){Button tools=Ui.redButton(this,"Physical Copy / Duplicate Tools");tools.setOnClickListener(v->startActivity(new Intent(this,PhysicalCopyActivity.class).putExtra("policy_id",id)));info.addView(tools);info.addView(Ui.sub(this,"Admin can preview/share the physical copy and delete a confirmed duplicate from this policy."));}}
 void detail(String label,String value){if(value!=null&&!value.trim().isEmpty())info.addView(Ui.sub(this,label+": "+value));}
 void runAction(String path,JSONObject body,boolean share){Ui.run(this,()->{try{JSONObject result=ApiClient.post(this,path,body);Ui.ui(this,()->{if(share){String url=result.optString("url",result.optString("share_url",""));if(url.isEmpty()){Ui.toast(this,result.optString("message","Link unavailable"));return;}Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,url);startActivity(Intent.createChooser(send,"Share policy link"));}else Ui.toast(this,result.optString("message","Email request completed"));});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
